#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-railway (railway-deploy) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Deploys Railway project game to one environment from the model:
#   1. copies the secrets from the vault (deploy/sync-secrets.sh),
#   2. plans and applies `.railway/railway.ts` (`railway config plan`, then `apply`),
#   3. with --redeploy, redeploys each service and waits for its health path,
#   4. runs deploy/doctor.sh.
# A push to the deployment's branch also deploys on Railway; this script is for settings and
# secrets, and for a deploy that cannot wait for a push. --yes applies without the prompt
# (never a destructive change: Railway refuses one without --confirm-destructive).
#
# Needs: railway (logged in, run from the linked repository), keys-axi, jq, npm, curl.
#
#   bash deploy/deploy.sh <environment> [--yes] [--redeploy]
set -euo pipefail
cd "$(dirname "$0")/.."

ENVIRONMENT="${1:-}"
YES=(); REDEPLOY=0
for arg in "${@:2}"; do
  case "$arg" in
    --yes) YES=(--yes) ;;
    --redeploy) REDEPLOY=1 ;;
    *) echo 'usage: bash deploy/deploy.sh <environment> [--yes] [--redeploy]' >&2; exit 2 ;;
  esac
done
ensure_sdk() {
  [ -d .railway/node_modules/railway ] || npm install --no-save --prefix .railway railway@3.17.0 >/dev/null
}

# wait_healthy <url> <seconds>
wait_healthy() {
  local deadline=$((SECONDS + $2))
  until curl -fsS -o /dev/null --max-time 10 "$1"; do
    [ "$SECONDS" -lt "$deadline" ] || { echo "deploy: $1 did not answer 2xx within $2 seconds" >&2; return 1; }
    sleep 10
  done
  echo "healthy: $1"
}

# settle <environment>: sync secrets, then plan and apply the file
settle() {
  bash deploy/sync-secrets.sh "$1"
  railway environment "$1" >/dev/null
  ensure_sdk
  railway config plan
  railway config apply "${YES[@]}"
}

case "$ENVIRONMENT" in
  production)
    settle production
    if [ "$REDEPLOY" = 1 ]; then
      railway redeploy --service game --yes
    fi
    bash deploy/doctor.sh production
    ;;
  *) echo 'usage: bash deploy/deploy.sh <environment> [--yes] [--redeploy] (environments: production)' >&2; exit 2 ;;
esac
